mapper.select:
SELECT , c.name AS categoryName, u.real_name AS userRealName FROM user_case uc LEFT JOIN category c ON c.id = uc.category_id LEFT JOIN user u ON u.id = uc.user_id
AND uc.user_id = #{userId}
AND uc.is_public = #{isPublic}
AND uc.title LIKE CONCAT('%', #{title}, '%')
AND uc.category_id = #{categoryId}
ORDER BY uc.update_time DESC, uc.id DESC

mapper.update:
UPDATE user_case
title = #{title}, patient_name = #{patientName}, age = #{age}, gender = #{gender}, category_id = #{categoryId}, remark = #{remark}, content = #{content}, ai_summary = #{aiSummary}, is_public = #{isPublic}, update_time = NOW()
WHERE id = #{id}
